 const enc=src.enc?{on:!!src.enc.on,items:(src.enc.items||[]).map(it0=>{const it=JSON.parse(JSON.stringify(it0));it.id=thUid();if(!thSongOk(S.songs[it.song],key))it.na=1;if(it.pt=='unit'&&umap[it.unit])it.unit=umap[it.unit];if(it.center!=null&&!B.includes(it.center))it.center=null;delete it.form;delete it.fo;if(it.cz&&!thCzOk(it.cz))it.cz=null;return it})}:{on:false,items:[]};
