 <div class="gekg">${thKpi('Next performance',nx?thSlotTxt(nx):'—',nx?esc((thStageFor(T,nx)||{}).name||'No Stage'):'')}${thKpi('Performances this week',week.length,week.map(x=>TH_DOW[dowOf(x.day)]+' '+TH_SLOT[x.sl][0]).join(' · '))}${thKpi('Avg. attendance',`${A.att}/${TH_CAP}`,'last 20 shows')}${thKpi('Avg. online viewers',A.on.toLocaleString())}${thKpi('Avg. ticket revenue',yen(A.rev))}${thKpi('Online members',subs.toLocaleString(),'active subscriptions')}${thKpi('Membership revenue',yen(mrev),'last month')}${thKpi('Total performances',A.n,A.n?`avg. satisfaction ${A.sat}%`:'')}</div>
